import "encore.dev/storage/sqldb"

// cleanupdb is the PostgreSQL database for the cleanup service.
// It is provisioned by Encore and the migrations are applied
// from the ./migrations directory at deploy time.
var cleanupdb = sqldb.NewDatabase("cleanup_db", sqldb.DatabaseConfig{
	Migrations: "./migrations",
})

CREATE TABLE records (
    id TEXT PRIMARY KEY,
    data TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL
);

package cleanup

import (
	"context"
	"time"
)

// Record represents a row in the records table as it is exchanged
// over the HTTP API.
type Record struct {
	ID        string `json:"id"`
	Data      string `json:"data"`
	CreatedAt string `json:"created_at"`
}

// CreateRecordParams is the request body for POST /records.
// CreatedAt is expected to be an RFC3339 formatted timestamp string.
type CreateRecordParams struct {
	ID        string `json:"id"`
	Data      string `json:"data"`
	CreatedAt string `json:"created_at"`
}

// CreateRecordResponse is the response body for POST /records.
type CreateRecordResponse struct {
	Record *Record `json:"record"`
}

// CreateRecord inserts a new record into the records table.
//
//encore:api public method=POST path=/records
func CreateRecord(ctx context.Context, p *CreateRecordParams) (*CreateRecordResponse, error) {
	createdAt, err := time.Parse(time.RFC3339, p.CreatedAt)
	if err != nil {
		return nil, err
	}

	_, err = cleanupdb.Exec(ctx, `
		INSERT INTO records (id, data, created_at)
		VALUES ($1, $2, $3)
	`, p.ID, p.Data, createdAt)
	if err != nil {
		return nil, err
	}

	return &CreateRecordResponse{
		Record: &Record{
			ID:        p.ID,
			Data:      p.Data,
			CreatedAt: p.CreatedAt,
		},
	}, nil
}

// ListRecordsResponse is the response body for GET /records.
type ListRecordsResponse struct {
	Records []*Record `json:"records"`
}

// ListRecords returns all records ordered by their created_at timestamp.
//
//encore:api public method=GET path=/records
func ListRecords(ctx context.Context) (*ListRecordsResponse, error) {
	rows, err := cleanupdb.Query(ctx, `
		SELECT id, data, created_at
		FROM records
		ORDER BY created_at ASC
	`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	records := []*Record{}
	for rows.Next() {
		var (
			id        string
			data      string
			createdAt time.Time
		)
		if err := rows.Scan(&id, &data, &createdAt); err != nil {
			return nil, err
		}
		records = append(records, &Record{
			ID:        id,
			Data:      data,
			CreatedAt: createdAt.UTC().Format(time.RFC3339),
		})
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	return &ListRecordsResponse{Records: records}, nil
}

package cleanup

import (
	"context"
	"time"

	"encore.dev/cron"
)

// CleanupResponse is the response body for POST /cleanup.
type CleanupResponse struct {
	DeletedCount int64 `json:"deleted_count"`
}

// Cleanup deletes records whose created_at is older than 24 hours.
// It is exposed as a public API so it can be invoked manually for
// verification, and it is also wired up to a Cron Job below.
//
//encore:api public method=POST path=/cleanup
func Cleanup(ctx context.Context) (*CleanupResponse, error) {
	cutoff := time.Now().Add(-24 * time.Hour)

	result, err := cleanupdb.Exec(ctx, `
		DELETE FROM records
		WHERE created_at < $1
	`, cutoff)
	if err != nil {
		return nil, err
	}

	return &CleanupResponse{DeletedCount: result.RowsAffected()}, nil
}

// CleanupCron runs every hour to remove stale records.
var _ = cron.NewJob("cleanup-old-records", cron.JobConfig{
	Title:    "Cleanup old records",
	Every:    1 * cron.Hour,
	Endpoint: Cleanup,
})

